final class MeasureRequest
{
    public function handle(Request $request, Closure $next): Response
    {
        $started = hrtime(true);

        try {
            return $next($request);
        } finally {
            Log::info('request.finished', [
                'elapsed_ns' => hrtime(true) - $started,
            ]);
        }
    }
}

