type Result =
  | { kind: 'ok'; value: string }
  | { kind: 'error'; message: string };

function render(result: Result): string {
  switch (result.kind) {
    case 'ok': return result.value;
    case 'error': return result.message;
    default: return result satisfies never;
  }
}

