type Action =
  | { type: "added"; item: Item }
  | { type: "removed"; id: number };

function cartReducer(state: Item[], action: Action): Item[] {
  switch (action.type) {
    case "added": return [...state, action.item];
    case "removed": return state.filter(item => item.id !== action.id);
  }
}

