type CartStore = {
  items: Item[];
  add: (item: Item) => void;
};

const useCart = create<CartStore>(set => ({
  items: [],
  add: item => set(state => ({ items: [...state.items, item] })),
}));

function CartCount() {
  const count = useCart(state => state.items.length);
  return <span>{count}</span>;
}

